// and switching guides; concept comparisons (getgradify.com/vs/…); and "alternatives" comparisons of other study
// apps (getgradify.com/compare/…). Every guide answers first, uses the questions students actually type as its
// headings, ends sections with a copyable key takeaway, and has a "test yourself" prompt or two.
import { faq, related, esc, toc, takeaway, selfTest, slugId, ORG } from "./shell.mjs";
import { GUIDE_EXTRA, VS_EXTRA, toolCallout, pitfallsBox, coreRule, relatedKeys, seriesNav, LINKS } from "./links.mjs";

const U = "2026-11-23";
const AUTHOR = { "@type": "Organization", "@id": "https://getgradify.com/#org", name: "Gradify", url: "https://getgradify.com/about.html" };
const byline = `<p class="byline">By the <a href="/about.html">Gradify team</a> · Updated for the 2026–27 academic year</p>`;
const T = (h, html, take = "", test = null) => ({ h, html, take, test });

// { slug, group, title, description, h1, answer, sections: [T], faq, links: [[href, label]], howto?: [steps] }
export const GUIDES2 = [
  // ---------- exam technique ----------
  { slug: "command-words", group: "exam", title: "Exam Command Words Explained (State, Explain, Evaluate) · Gradify", description: "What state, describe, explain, compare, evaluate and 'to what extent' want, with weak vs full-mark answers. For GCSE, A level, IB and university exams.",
    h1: "Exam command words: what each one wants", answer: "The command word tells you what kind of answer earns the marks: 'state' wants a fact, 'describe' wants what happens, 'explain' wants why or how, and 'evaluate' wants a judgement backed by evidence on both sides. Most lost marks on short answers come from answering a different command word from the one asked.",
    sections: [
      T("What's the difference between describe and explain?", `<div class="scroll"><table><thead><tr><th>Question</th><th>Weak answer</th><th>Full-mark approach</th></tr></thead><tbody><tr><td>Describe the trend in the graph.</td><td>"It goes up because more enzyme is made."</td><td>"The rate increases steadily from 10 to 40 °C, peaks at 40 °C (2.4 units), then falls sharply to zero by 60 °C." (Data quoted, no reasons.)</td></tr><tr><td>Explain the trend.</td><td>"The rate increases then decreases."</td><td>"Rate rises because molecules have more kinetic energy, so more successful collisions; above 40 °C hydrogen bonds break, the active site changes shape and fewer enzyme-substrate complexes form."</td></tr></tbody></table></div>`, "Describe = what happens (with data). Explain = why it happens (a cause linked to its effect).", ["A question says 'Describe the results'. Should you give reasons?", "No. Describe asks what the data show: trends, peaks and values with units. Reasons are for 'explain'."]),
      T("What do evaluate, assess and 'to what extent' want?", `<p>All three want a <b>judgement</b>: weigh points on both sides, say which matter more and why, and end with a supported conclusion. A list of pros and cons with no verdict usually caps you in the middle mark band. 'To what extent' wants a clear answer on a scale ("largely", "only partly") rather than yes or no.</p>`, "No verdict, no top band: evaluate questions are marked on the judgement."),
      T("Every common command word", `<div class="scroll"><table><thead><tr><th>Command word</th><th>What to do</th></tr></thead><tbody>${[["State / Give / Name", "A fact or name, no explanation."], ["Identify", "Pick it out from the information given."], ["Define", "The precise meaning, in the key terms the mark scheme expects."], ["Outline", "The main points, briefly."], ["Describe", "What happens or what it's like, step by step."], ["Explain", "Why or how: cause → effect, linked with 'because' or 'so'."], ["Calculate / Determine", "A number, with working and units."], ["Compare", "Similarities and differences, side by side ('whereas', 'both')."], ["Contrast", "Differences only, side by side."], ["Analyse", "Break into parts and show how they connect, with evidence."], ["Suggest", "Apply what you know to an unfamiliar situation."], ["Justify", "Reasons for a decision, each backed by evidence."], ["Discuss", "Arguments on more than one side, reaching a view."], ["Evaluate / Assess", "Weigh strengths and weaknesses, then judge."], ["To what extent", "How far it's true: both sides, then a clear verdict."]].map(([a, b]) => `<tr><th scope="row">${a}</th><td>${b}</td></tr>`).join("")}</tbody></table></div><p>Exam boards publish their own lists (AQA, OCR, Pearson Edexcel and the IB each have one). The meanings above are common to all of them, but check your board's list for subject-specific words.</p>`),
      T("How do I practise command words?", `<p>Take five past-paper questions, underline the command word, and write only the first sentence of each answer. Check: does that sentence do what the word asks? Then use the <a href="/tools/question-deconstructor/">question deconstructor</a> on anything unfamiliar, and log misreads in your <a href="/tools/mistake-log/">mistake log</a>.</p>`, "", ["What does 'compare' need that 'describe' doesn't?", "Both things in every sentence, with a linking word such as 'whereas' or 'both', so the similarity or difference is explicit."]),
    ],
    faq: [["What does explain mean in an exam?", "Give reasons: say why or how something happens, linking each cause to its effect. Each correct link usually earns a mark."], ["What's the difference between evaluate and discuss?", "Discuss wants arguments on more than one side; evaluate also wants a final judgement about which side is stronger, backed by evidence."]],
    links: [["tools/question-deconstructor/", "Question deconstructor"], ["guides/question-stems/", "Question stems"], ["guides/long-answer-questions/", "Long-answer questions"]] },
  { slug: "question-stems", group: "exam", title: "Exam Question Stems and How to Answer Each One · Gradify", description: "Common exam question stems (account for, suggest why, compare the mechanisms, design an investigation) with a step-by-step response skeleton for each.",
    h1: "Exam question stems and the answer skeleton for each", answer: "Unfamiliar exam questions are usually familiar stems in disguise: 'account for this anomaly', 'suggest why', 'compare these two', 'design an investigation'. Each stem has a skeleton answer you can learn, so on the day you fill in content instead of inventing a structure.",
    sections: [
      T("How do I answer 'suggest why'?", `<p>'Suggest' means the answer isn't in the specification word for word: apply a principle you know to a new case. Skeleton: <b>name the principle → apply it to this context → state the consequence</b>. Any plausible, scientifically sound answer usually earns credit.</p>`, "Suggest = principle → this context → consequence."),
      T("How do I answer 'account for the anomaly'?", `<p>Skeleton: <b>identify the anomalous value → name a specific error that would push it in that direction → explain the direction</b> ("the reading is too high because heat was lost, so less…"). Vague answers like "human error" score nothing.</p>`, "Name a specific error and the direction it pushes the result."),
      T("How do I answer 'compare the mechanisms'?", `<p>Skeleton: <b>one shared feature, then two or three differences, each sentence naming both</b>. Use a quick two-column plan first. Marks go to explicit comparison ("whereas SN1 goes via a carbocation, SN2 is a single step"), not two separate descriptions.</p>`),
      T("How do I answer 'design an investigation'?", `<p>Skeleton: <b>independent variable and its range → dependent variable and how it's measured → control variables and how each is kept constant → repeats and means → safety</b>. See <a href="/guides/variables-and-controls/">variables and controls</a>.</p>`, "Design = IV with range, DV with method, controls with how, repeats, safety.", ["What's missing from 'keep the temperature the same' as a control?", "How: for example 'use a thermostatic water bath at 25 °C'. Naming a control without the method usually loses the mark."]),
      T("How do I answer 'evaluate the claim'?", `<p>Skeleton: <b>what supports the claim (with evidence) → what limits it (sample, method, alternative explanation) → judgement with a reason</b>. End with a sentence that starts "Overall…" and answers the question.</p>`),
    ],
    faq: [["What is a question stem?", "The opening phrase of an exam question that sets the task, such as 'suggest why' or 'compare'. Learning a skeleton answer for each common stem saves time and marks."]],
    links: [["guides/command-words/", "Command words"], ["tools/question-deconstructor/", "Question deconstructor"], ["questions/", "Practice questions"]] },
  { slug: "exam-technique", group: "exam", title: "Exam Technique: Timing, Planning and Checking for Marks · Gradify", description: "Exam technique that adds marks without more content: time per mark, the order to answer in, how to break down multi-part questions and what to check at the end.",
    h1: "Exam technique: how to get the marks you already know", answer: "Good exam technique turns what you know into marks: spend about 1 to 1.5 minutes per mark, read every question's command word and constraints before writing, answer the questions you're surest of first, and keep five minutes to check units, names and missed parts.",
    sections: [
      T("How long should I spend on each question?", `<p>Divide the exam length by the total marks. A 2-hour paper with 100 marks gives 1.2 minutes a mark, so a 6-mark question gets about 7 minutes. Write the finish time for each section on the paper at the start. If a question is taking much longer than its marks justify, move on and come back.</p>`, "Minutes per mark = exam minutes ÷ total marks. Stick to it."),
      T("How do I break down a multi-part question?", `<p>Use four steps: <b>read the constraints</b> (command word, marks, "using the data"), <b>identify the concept</b> being tested, <b>map one point per mark</b>, then <b>check units and relevance</b>. The <a href="/tools/question-deconstructor/">question deconstructor</a> walks you through it for any question you paste.</p>`, "", ["A 4-mark 'explain' question: how many linked points should you plan?", "About four creditable points, each a cause linked to its effect."]),
      T("What order should I answer questions in?", `<p>Skim the paper, then start with a question you're confident on: early marks calm nerves and bank time. Don't leave the long, high-mark questions until the last ten minutes.</p>`),
      T("What should I check at the end?", `<ul><li>Every part answered (look for questions on the back of pages).</li><li>Units and significant figures on every calculation.</li><li>Names, candidate numbers and question numbers.</li><li>Command words: did you explain where it said explain?</li></ul>`),
    ],
    faq: [["How can I improve my exam technique quickly?", "Do one timed past paper, mark it with the mark scheme, and log why you dropped each mark. Most students find a pattern (misreading, timing, missing units) that's quick to fix."]],
    links: [["tools/question-deconstructor/", "Question deconstructor"], ["tools/mistake-log/", "Mistake log"], ["checklists/exam-day/", "Exam day checklist"]] },
  { slug: "long-answer-questions", group: "exam", title: "How to Answer 6-Mark and 8-Mark Exam Questions · Gradify", description: "Plan a 6- or 8-mark answer in 60 seconds: core point or mechanism, evidence or example, link back to the question, evaluation. With weak vs strong outlines.",
    h1: "How to answer 6-mark and 8-mark questions", answer: "Long-answer questions are usually marked by levels: examiners look for a logical chain of correct points, not a list. Spend 60 seconds planning: core point or mechanism, evidence or an example, a link back to the question, and (if the command word asks) an evaluation.",
    sections: [
      T("How are 6-mark questions marked?", `<p>Most boards use <b>levels of response</b>: the examiner reads the whole answer and places it in a level (for example 1–2, 3–4 or 5–6 marks) by the quality of the reasoning, then picks a mark within it. A long list of disconnected facts often sits in the middle level.</p>`, "Levels marking rewards a linked chain of reasoning, not the number of facts."),
      T("What does a strong outline look like?", `<div class="scroll"><table><thead><tr><th>Weak outline</th><th>Strong outline</th></tr></thead><tbody><tr><td>Fact, fact, fact, fact (no links)</td><td>1. Core point that answers the question → 2. How or why (mechanism) → 3. Evidence or example → 4. Second point, linked → 5. Evaluation or limitation → 6. Conclusion that answers the question</td></tr></tbody></table></div>`, "", ["Your 6-mark answer lists four correct facts. Why might it still get 3/6?", "Levels marking rewards a linked, logical chain that answers the question; unlinked facts usually sit in a middle level."]),
      T("How long should a 6-mark answer be?", `<p>Usually 120 to 200 words, or about 7 to 9 minutes. Use the lines given as a guide, not a target.</p>`),
    ],
    faq: [["How many points do I need for a 6-mark question?", "There's no fixed number in levels-marked questions; what matters is a correct, logically linked chain that answers the command word. As a rough guide, three well-developed points beat six bare ones."]],
    links: [["guides/command-words/", "Command words"], ["tools/mark-scheme-checker/", "Mark scheme checker"], ["guides/definitions-vs-explanations/", "Definitions vs explanations"]] },
  { slug: "definitions-vs-explanations", group: "exam", title: "Definitions vs Explanations: Matching the Mark Scheme · Gradify", description: "When to give a crisp technical definition, a step-by-step explanation or an evaluation, with side-by-side examples, so your answer matches the mark scheme.",
    h1: "Definitions vs explanations: give the depth the marks ask for", answer: "A definition is one precise sentence in technical terms; an explanation is a chain of steps showing how or why; an evaluation weighs it up. Students lose easy marks by giving an everyday description when a definition is asked for, or a one-line definition for a 4-mark explanation.",
    sections: [
      T("What does a good definition look like?", `<p>"Osmosis is the net movement of water molecules from a region of higher water potential to a region of lower water potential through a partially permeable membrane." Every highlighted term (net, water potential, partially permeable) is a mark-scheme word. "Water moving through a membrane" misses all of them.</p>`, "Definitions are marked on exact key terms: learn them word for word with flashcards."),
      T("Definition, explanation or evaluation?", `<div class="scroll"><table><thead><tr><th>Asked for</th><th>Depth</th><th>Example on osmosis</th></tr></thead><tbody><tr><td>Define (1–2 marks)</td><td>One precise sentence</td><td>The definition above</td></tr><tr><td>Explain (3–4 marks)</td><td>Steps linked by because/so</td><td>Why a red blood cell bursts in pure water</td></tr><tr><td>Evaluate (6+ marks)</td><td>Steps plus judgement</td><td>How useful potato-chip experiments are for measuring water potential</td></tr></tbody></table></div>`, "", ["'Explain why a plant cell doesn't burst in pure water' (3 marks). Is a definition of osmosis enough?", "No: you need the chain: water enters by osmosis → the cell swells → the cell wall resists expansion, so pressure builds and stops further net entry."]),
    ],
    faq: [["How do I learn definitions for exams?", "Make one flashcard per definition, answer it from memory word for word, and check every key term against the mark scheme or textbook."]],
    links: [["guides/command-words/", "Command words"], ["guides/long-answer-questions/", "Long-answer questions"], ["glossary/", "Study glossary"]] },
  { slug: "mcq-traps", group: "exam", title: "Multiple-Choice Exam Traps and How to Spot Them · Gradify", description: "How multiple-choice distractors are built: true statements that don't answer the question, reversed cause and effect, absolutes like always or never, and unit slips.",
    h1: "Multiple-choice traps: how distractors are built", answer: "Wrong options in a good multiple-choice question are built to catch specific mistakes. The four most common traps are a true statement that doesn't answer the question, reversed cause and effect, extreme absolutes like 'always' or 'never', and a unit or scale slip. Name the trap and the wrong option loses its pull.",
    sections: [
      T("Trap 1: a true statement that doesn't answer the question", `<p>The option is correct science but answers a different question. Re-read the stem after choosing: does your option answer <i>this</i> question?</p>`, "True isn't enough: it has to answer this question."),
      T("Trap 2: reversed cause and effect", `<p>"Increased heart rate causes exercise" sounds familiar because the right words are there in the wrong order. Check the direction of every 'causes', 'leads to' or 'because'.</p>`),
      T("Trap 3: always, never, only, all", `<p>Absolute words are rarely true in biology, medicine or the social sciences. They're not automatically wrong, but they need one counter-example to fail.</p>`),
      T("Trap 4: unit and scale slips", `<p>Options that differ by a factor of 10 or 1,000 test whether you converted mg to g or cm³ to dm³. Do the unit check before looking at the options. The <a href="/tools/unit-converter/">unit converter</a> shows the factors.</p>`, "", ["Two options are 0.25 and 250. What's the trap likely to be?", "A unit conversion by a factor of 1,000, such as cm³ to dm³ or mg to g."]),
      T("How should I approach a multiple-choice question?", `<ol><li>Cover the options and answer from memory.</li><li>Find your answer among the options.</li><li>Check each remaining option for one of the four traps.</li><li>If you guessed, mark it and log it: a lucky guess is still a gap.</li></ol>`),
    ],
    faq: [["Is it better to guess on multiple choice?", "If there's no negative marking, never leave one blank: eliminate what you can and guess. Then treat every guess as a gap to revise, even if it was right."]],
    links: [["topics/", "Topic quizzes"], ["questions/", "Practice questions"], ["tools/mistake-log/", "Mistake log"]] },
  { slug: "graph-reading", group: "exam", title: "How to Read Graphs and Data in Exams (4-Check Scan) · Gradify", description: "Stop losing marks on data questions: a fast 4-check scan of axes and units, scale and log axes, trend vs anomaly, and caveats like error bars and controls.",
    h1: "Reading graphs and data: the 4-check scan", answer: "Before you describe any graph, scan four things: the axes and their units, the scale (is it linear or logarithmic, does it start at zero?), the overall trend versus any anomaly, and the caveats (error bars, sample size, control group). Most data-question marks are lost on one of these four.",
    sections: [
      T("1. Axes and units", `<p>Read both axis labels and units aloud. Quote values with units in your answer: "rises from 2.0 to 6.5 mmol dm⁻³", not "goes up".</p>`, "Quote numbers with units every time."),
      T("2. Scale: linear, log, or not starting at zero", `<p>On a log scale each gridline is ten times the last, so a straight line means exponential change. A y-axis that starts at 90 makes small differences look huge.</p>`),
      T("3. Trend vs anomaly", `<p>Describe the overall pattern first (direction, where it changes, the peak), then point out any anomalous point separately. Don't build your conclusion on one odd value.</p>`),
      T("4. Caveats: error bars, sample size, controls", `<p>Overlapping error bars (standard deviation or confidence intervals) mean a difference may not be significant. Small samples and missing controls limit what you can conclude: say so in 'evaluate' questions.</p>`, "", ["Two bars differ but their error bars overlap a lot. What should you conclude?", "The difference may not be significant; you can't confidently say one is higher than the other."]),
      T("Correlation or cause?", `<p>A graph showing two things rising together shows correlation. Causation needs a mechanism and a controlled comparison: see <a href="/vs/correlation-vs-causation/">correlation vs causation</a>.</p>`),
    ],
    faq: [["How do I describe a graph in an exam?", "State the overall trend, quote specific values with units at key points (start, peak, change), and mention any anomaly separately. Only explain reasons if the command word asks."]],
    links: [["guides/variables-and-controls/", "Variables and controls"], ["vs/correlation-vs-causation/", "Correlation vs causation"], ["checklists/lab-report/", "Lab report checklist"]] },
  { slug: "variables-and-controls", group: "exam", title: "Independent, Dependent and Control Variables Explained · Gradify", description: "Independent vs dependent vs control variables, with 'naming vs controlling' examples: the difference between losing and getting the mark in practicals and exams.",
    h1: "Variables and controls: naming vs controlling", answer: "The independent variable is what you change, the dependent variable is what you measure, and control variables are everything you keep the same. The mark usually goes for saying how you keep a control constant (a water bath at 25 °C), not just naming it (temperature).",
    sections: [
      T("Which variable is which?", `<div class="scroll"><table><thead><tr><th>Variable</th><th>Meaning</th><th>Enzyme example</th></tr></thead><tbody><tr><td>Independent</td><td>What you deliberately change</td><td>Temperature: 20, 30, 40, 50, 60 °C</td></tr><tr><td>Dependent</td><td>What you measure</td><td>Time for the starch to disappear (s)</td></tr><tr><td>Control</td><td>What you keep the same</td><td>pH, enzyme and substrate concentration, volumes</td></tr></tbody></table></div>`, "Change one (independent), measure one (dependent), keep the rest the same (controls)."),
      T("Naming vs controlling: where the marks are", `<div class="scroll"><table><thead><tr><th>Naming (often 0 marks)</th><th>Controlling (the mark)</th></tr></thead><tbody><tr><td>Keep the pH the same</td><td>Add 1 cm³ of pH 7 buffer to every tube</td></tr><tr><td>Same temperature</td><td>Place tubes in a thermostatic water bath at 25 °C</td></tr><tr><td>Same amount of enzyme</td><td>Use 2 cm³ of 1% amylase, measured with a graduated pipette</td></tr></tbody></table></div>`, "", ["How would you control light intensity in a photosynthesis experiment?", "Keep the lamp at a fixed, measured distance (e.g. 20 cm) and use the same bulb; block other light sources."]),
      T("What's a control group?", `<p>A control group (or control experiment) is identical except it doesn't get the independent variable, for example boiled enzyme or a placebo. It shows that the effect is caused by the independent variable and not something else.</p>`),
    ],
    faq: [["What is a control variable?", "A variable kept the same throughout an experiment so it can't affect the results. You should say how it's kept constant, not just name it."]],
    links: [["checklists/stem-practical/", "STEM practical checklist"], ["checklists/lab-report/", "Lab report checklist"], ["guides/graph-reading/", "Reading graphs"]] },
  { slug: "unit-conversion", group: "exam", title: "Unit Conversion Traps in Science Exams (and the Fix) · Gradify", description: "The unit slips that cost marks in chemistry, biology, physics and pharmacology: mol vs mmol, µg vs mg, cm³ vs dm³, kJ vs J, and a 3-second sanity check.",
    h1: "Unit conversion traps in science exams", answer: "Most unit mistakes are factor-of-1,000 slips: cm³ to dm³, mg to g, mmol to mol, J to kJ. The 3-second check: converting to a smaller unit gives a bigger number, and converting to a bigger unit gives a smaller one. The free unit converter shows the factor for any pair.",
    sections: [
      T("The top unit traps", `<ul><li><b>cm³ vs dm³</b>: titration volumes are in cm³; concentrations are mol dm⁻³. Divide cm³ by 1,000.</li><li><b>µg vs mg</b>: 1 mg = 1,000 µg. In drug doses this slip is a thousand-fold error.</li><li><b>mmol vs mol</b>: 1 mmol = 0.001 mol.</li><li><b>kJ vs J</b>: q = mcΔT gives joules; ΔH is usually quoted in kJ mol⁻¹.</li><li><b>°C vs K</b>: add 273 for kelvin in gas law and Arrhenius calculations.</li><li><b>Percent by mass vs molarity</b>: different quantities, not just different units.</li></ul>`, "A smaller unit always gives a bigger number. Check every answer against that."),
      T("How do I avoid unit mistakes?", `<p>Write the units on every line of working, not just the answer. Convert everything into the units the equation needs before substituting. Then do a sense check: is a concentration of 250 mol dm⁻³ plausible? (No.)</p>`, "", ["25.0 cm³ of 0.100 mol dm⁻³ NaOH: how many moles?", "25.0 ÷ 1,000 = 0.0250 dm³; 0.0250 × 0.100 = 0.00250 mol (2.50 mmol)."]),
    ],
    faq: [["How do I convert cm³ to dm³?", "Divide by 1,000. 1 dm³ = 1,000 cm³ = 1 litre."]],
    links: [["tools/unit-converter/", "Unit converter"], ["vs/molarity-vs-molality/", "Molarity vs molality"], ["topics/chemistry/", "Chemistry topics"]] },
  { slug: "open-book-exams", group: "exam", title: "How to Prepare for Open-Book and Take-Home Exams · Gradify", description: "Open-book exams still need revision. Build a one-page rapid-lookup index of formulas, definitions and where to find worked examples, and practise under time.",
    h1: "Open-book and take-home exams: how to prepare", answer: "Open-book exams test understanding and application, not memory, and the clock is the real enemy: students who haven't revised lose time flipping through PDFs. Revise as normal, then build a one-page index of formulas, definitions and where each worked example lives, and practise one timed paper with it.",
    sections: [
      T("Do you need to revise for an open-book exam?", `<p>Yes. Questions are harder because notes are allowed: they ask you to apply and evaluate. If you have to look up the basics, you won't have time to answer.</p>`, "Open book means harder questions, not less revision."),
      T("How do I build a rapid-lookup index?", `<ol><li>One page per module: key formulas, definitions you might quote, and the page or file where each worked example is.</li><li>Colour or tab by topic.</li><li>Number your notes' pages and put those numbers in the index.</li><li>Make a <a href="/notes-to-cheat-sheet/">one-page summary sheet</a> from your notes as the front page.</li></ol>`, "", ["What's the most useful thing on an open-book index?", "Where to find each worked example and formula fast (page numbers or file names), so you spend exam time applying, not searching."]),
      T("Take-home exams: what changes?", `<p>Over 24 or 48 hours, time management and referencing matter more. Plan the hours (the <a href="/tools/deadline-planner/">deadline planner</a> works for this), cite sources properly, and follow your university's rules on collaboration and AI tools.</p>`),
    ],
    faq: [["Are open-book exams easier?", "Usually not: they're designed so looking things up doesn't give you the answer. They reward understanding, application and fast navigation of your notes."]],
    links: [["notes-to-cheat-sheet/", "Notes to cheat sheet"], ["tools/deadline-planner/", "Deadline planner"], ["tools/citation-helper/", "Citation helper"]] },
  // ---------- seasonal and recovery ----------
  { slug: "winter-revision-plan", group: "season", title: "Winter Break Revision Plan for January Exams and Resits · Gradify", description: "How to use the Christmas break before January exams or resits: rest first, light spaced reviews so nothing fades, then focused exam blocks. With a free planner.",
    h1: "A winter break revision plan for January exams", answer: "Rest properly first, then keep the term's material alive with 20 minutes of flashcards a day, and save the intensive revision (two 50-minute blocks plus past questions a day) for the last two weeks. That beats both ignoring revision until New Year and burning out before Christmas.",
    sections: [
      T("Should I rest or revise over Christmas?", `<p>Both, in that order. Three to five days of real rest after term reduces burnout. Then short daily reviews stop the forgetting curve wiping out the term, which makes January's focused revision much faster.</p>`, "Rest, then light daily reviews, then focus: in that order."),
      T("What does a light day look like?", `<p>Twenty minutes of flashcards on the cards that are due, and nothing else. It keeps memories alive at almost no cost.</p>`),
      T("What does a focus day look like?", `<p>Two 50-minute blocks: one on your weakest topic, one on timed past-paper questions. Then flashcards. Use the <a href="/tools/winter-revision-planner/">winter revision planner</a> to lay out your days and the <a href="/tools/exam-timetable-planner/">exam timetable planner</a> if you have several exams.</p>`, "", ["You have 30 days until a January exam. Roughly how many should be focus days?", "About the last 40%: 12 or so, after rest days and light days."]),
    ],
    faq: [["How many hours should I revise over Christmas?", "For January exams, a common pattern is very little in the first week, 20 to 30 minutes a day in the middle, and 2 to 4 focused hours a day in the last two weeks."]],
    links: [["tools/winter-revision-planner/", "Winter revision planner"], ["guides/exam-resit-recovery/", "Exam resit recovery"], ["tools/exam-timetable-planner/", "Exam timetable planner"]] },
  { slug: "freshers-study-system", group: "season", title: "A First-Year University Study System That Works · Gradify", description: "Set up a simple study system in freshers' week: one folder per module, notes the same day, weekly reviews, flashcards from the start, and a baseline quiz.",
    h1: "A first-year study system: set it up in freshers' week", answer: "A simple system beats a perfect one: one folder per module, notes filed the same day, one weekly review session per module, and flashcards made as you go rather than in May. Set it up in an evening in the first week and you'll never face a semester of unread notes.",
    sections: [
      T("What should I set up before lectures start?", `<p>Module list with credits and assessment dates in your calendar, one folder per module, and a weekly review slot. The <a href="/checklists/semester-reset/">semester reset checklist</a> covers it.</p>`, "One folder per module, notes filed the same day, one review slot a week."),
      T("How do I take notes in lectures?", `<p>Don't transcribe. Note the structure, examples and anything the lecturer says is important; fill gaps from the slides later. Turn headings into questions (the <a href="/glossary/cornell-notes/">Cornell method</a>), or <a href="/pdf-to-flashcards/">turn the slides into flashcards</a> the same week.</p>`),
      T("Does first year count?", `<p>At most UK universities, first-year marks don't count towards your degree classification, but the content does: second and final year build on it. A good system now saves months later.</p>`, "", ["Why make flashcards in week 1 instead of before exams?", "Spaced repetition needs time: cards made in week 1 can be reviewed many times at growing gaps before the exam, which is far more effective than cramming them in May."]),
    ],
    faq: [["How many hours should a first-year student study?", "UK degrees assume about 10 hours of learning per credit, so a 120-credit year is roughly 1,200 hours, around 35 to 40 hours a week in term including lectures."]],
    links: [["checklists/semester-reset/", "Semester reset checklist"], ["tools/study-hours-calculator/", "Study hours calculator"], ["guides/study-methods/", "Study methods compared"]] },
  { slug: "exam-resit-recovery", group: "season", title: "Failed an Exam? A Resit Recovery Plan That Works · Gradify", description: "Failed a module or exam? How to read your feedback, find what actually went wrong, and build a resit revision plan, without panic. With free planners.",
    h1: "Failed an exam? A resit recovery plan", answer: "A failed exam is information, not a verdict. Get your feedback and script if you can, find out whether the problem was content, exam technique or time, check what your resit rules are, then build a plan aimed at that specific cause. Most resits are passed by students who change their method, not just their hours.",
    sections: [
      T("What should I do first after failing an exam?", `<ol><li>Give yourself a day.</li><li>Read the feedback and, if your university allows, request your script.</li><li>Check your regulations: when the resit is, whether the mark is capped, and whether compensation applies (see <a href="/guides/resits-and-compensation/">resits and compensation</a>).</li><li>Talk to your personal tutor: they've seen this many times.</li></ol>`, "Read the feedback before you plan: the fix depends on the cause."),
      T("Was it content, technique or time?", `<p>Content gaps show up as blank or wrong answers on whole topics. Technique shows up as dropped marks on questions you knew (misread command words, no evaluation). Time shows up as unfinished questions. Log each lost mark in the <a href="/tools/mistake-log/">mistake log</a> to see the split.</p>`),
      T("How do I plan the resit?", `<p>Rank topics with the <a href="/tools/topic-prioritiser/">topic prioritiser</a>, plan hours with the <a href="/tools/exam-countdown/">exam countdown</a>, and switch from re-reading to <a href="/guides/active-recall/">active recall</a> and past papers.</p>`, "", ["You lost most marks on questions you knew. Content or technique?", "Technique: the fix is reading command words, planning answers and timing, not more content."]),
      T("Where can I get support?", `<p>Your personal tutor, your university's academic skills team and its wellbeing service. If something outside your control affected the exam, ask about extenuating (mitigating) circumstances: deadlines for claims are usually strict.</p>`),
    ],
    faq: [["Can I resit a failed exam at university?", "Usually yes, at least once. Rules on timing, capped marks and how many attempts you get vary by university: check your academic regulations or ask your tutor."]],
    links: [["guides/resits-and-compensation/", "Resits and compensation explained"], ["tools/cram-planner/", "Cram planner"], ["tools/mistake-log/", "Mistake log"]] },
  { slug: "resits-and-compensation", group: "season", title: "University Resits, Capped Marks and Compensation Explained · Gradify", description: "How UK university resits work: capped vs uncapped marks, compensation and condonement, credit weighting, and what to ask your department. Check your own regulations.",
    h1: "Resits, capped marks and compensation, explained", answer: "At most UK universities, a failed module can be resat, but the resit mark is often capped at the pass mark (usually 40% for undergraduates). Some universities also compensate or condone a narrowly failed module if your other marks are strong. The rules differ a lot between universities, so treat this as a guide to the questions to ask, and check your own regulations.",
    sections: [
      T("What is a capped resit mark?", `<p>If you pass a resit, the module mark recorded is often capped at the pass mark (for example 40%), even if you scored higher. A <b>first sit</b> (granted when extenuating circumstances are accepted) is usually uncapped.</p>`, "A resit often counts as 40% however well you do: a first sit is usually uncapped."),
      T("What are compensation and condonement?", `<p><b>Compensation</b> lets a narrowly failed module (for example 30–39%) pass on the strength of your other marks, usually with limits on how many credits. <b>Condonement</b> is similar: the fail stands but you're awarded the credit. Not every university uses them, and professional degrees (medicine, nursing, pharmacy) often don't allow them for core modules.</p>`),
      T("What should I ask my department?", `<ul><li>Is the resit mark capped, and at what?</li><li>Is compensation or condonement possible for this module?</li><li>When is the resit, and is it the same format?</li><li>Does it affect progression or my classification?</li><li>Can I submit extenuating circumstances, and by when?</li></ul>`, "", ["Your resit is capped at 40%. Why does how well you do still matter?", "You still need to pass, and the knowledge carries into later modules and exams that do count."]),
    ],
    faq: [["Is a resit capped at 40%?", "Often, for undergraduates at UK universities, but not always: it depends on your university's regulations and whether extenuating circumstances were accepted."]],
    links: [["guides/exam-resit-recovery/", "Resit recovery plan"], ["tools/module-grade-calculator/", "Module grade calculator"], ["tools/degree-classification-calculator/", "Degree classification calculator"]] },
  // ---------- methods ----------
  { slug: "study-myths", group: "method", title: "7 Study Myths That Waste Your Revision Time · Gradify", description: "Highlighting, re-reading, learning styles, multitasking and trusting unchecked AI notes: what the research says about common study myths, and what to do instead.",
    h1: "Seven study myths that waste revision time", answer: "Many of the most popular study habits (highlighting, re-reading, studying to your 'learning style', multitasking, and trusting AI summaries without checking) feel productive but do little for exam performance. The swaps are simple: test yourself, space your reviews, and check what you study against the source.",
    sections: [
      T("Myth 1: highlighting helps you remember", `<p>A 2013 review by Dunlosky and colleagues rated highlighting as low utility. It feels like work, but it doesn't make you retrieve anything. <b>Swap:</b> turn each highlight into a question and answer it later.</p>`, "Turn highlights into questions."),
      T("Myth 2: re-reading is revising", `<p>Re-reading builds familiarity, which feels like knowing. Testing yourself shows what you can actually recall. See <a href="/guides/active-recall-vs-rereading/">active recall vs re-reading</a>.</p>`),
      T("Myth 3: you have a learning style", `<p>Matching teaching to visual, auditory or kinaesthetic 'styles' hasn't held up in controlled studies. What helps everyone is combining words and pictures (<a href="/glossary/dual-coding/">dual coding</a>).</p>`),
      T("Myth 4: multitasking while revising works", `<p>Switching between revision and messages costs attention every time. Use a <a href="/tools/study-timer/">focus timer</a> and keep your phone out of the room.</p>`),
      T("Myth 5: cramming works", `<p>It can get you through tomorrow, but most of it is gone in a week. Spacing the same hours across days gives far better long-term memory (the <a href="/glossary/spacing-effect/">spacing effect</a>).</p>`),
      T("Myth 6: AI notes don't need checking", `<p>AI tools can state wrong facts fluently. If you revise from AI-made material, check it against your lecture notes or textbook. Gradify links every card to the line it came from and marks mismatches <i>to check</i> for this reason.</p>`, "Check AI-made notes against your source before you learn them."),
      T("Myth 7: more hours means better grades", `<p>An hour of testing yourself beats three hours of re-reading. Count recall, not hours.</p>`, "", ["Which two techniques did the 2013 Dunlosky review rate as high utility?", "Practice testing (retrieval practice) and distributed practice (spacing)."]),
    ],
    faq: [["Is highlighting a good study technique?", "On its own, no: research rates it low utility. It's fine as a first step if you then turn the highlighted points into questions and test yourself."]],
    links: [["guides/active-recall/", "The complete guide to active recall"], ["guides/study-methods/", "Study methods compared"], ["glossary/", "Study glossary"]] },
  { slug: "study-methods", group: "method", title: "Study Methods Compared: Active Recall, Blurting, Pomodoro · Gradify", description: "Active recall vs spaced repetition vs Leitner vs blurting vs Pomodoro vs time-blocking: what each is best for, setup time, the main pitfall and how to try it free.",
    h1: "Study methods compared: which fits your workload?", answer: "The two methods with the strongest evidence are active recall (testing yourself) and spaced repetition (spreading reviews out). Blurting, flashcards and the Leitner system are ways of doing active recall; Pomodoro and time-blocking are ways of organising your time. Use one of each.",
    sections: [
      T("Which study method is best?", `<div class="scroll"><table><thead><tr><th>Method</th><th>Best for</th><th>Setup</th><th>Main pitfall</th><th>Try it free</th></tr></thead><tbody>${[["Active recall", "Everything: the core method", "None", "Peeking too soon", '<a href="/guides/active-recall/">Guide</a>'], ["Spaced repetition", "Facts and definitions over weeks", "A schedule or app", "Skipping days, then a pile-up", '<a href="/tools/spaced-repetition-schedule/">Schedule</a>'], ["Flashcards", "Definitions, short processes", "Making cards", "Cards too big to mark", '<a href="/pdf-to-flashcards/">From a PDF</a>'], ["Leitner boxes", "Paper flashcards", "Five boxes", "Losing track of boxes", '<a href="/glossary/leitner-system/">How it works</a>'], ["Blurting", "Whole topics, essay plans", "A blank page", "Not checking afterwards", '<a href="/guides/blurting-method/">Guide</a>'], ["Pomodoro", "Starting and staying focused", "A timer", "Breaks on your phone", '<a href="/tools/study-timer/">Timer</a>'], ["Time-blocking", "Busy weeks, many modules", "A calendar", "Over-filling the plan", '<a href="/tools/exam-timetable-planner/">Planner</a>']].map((r) => `<tr>${r.map((x, i) => (i ? `<td>${x}</td>` : `<th scope="row">${x}</th>`)).join("")}</tr>`).join("")}</tbody></table></div>`, "Pick one recall method and one time method: they do different jobs."),
      T("Can I combine study methods?", `<p>Yes, and you should: for example Pomodoro blocks, each spent on blurting a topic then checking it with flashcards that are scheduled by spaced repetition.</p>`, "", ["Is Pomodoro an alternative to active recall?", "No: Pomodoro organises time; active recall is what you do inside the time. Use both."]),
    ],
    faq: [["What is the most effective study method?", "Practice testing (active recall) and distributed practice (spaced repetition) have the strongest research support. Other methods are ways of doing or scheduling those two."]],
    links: [["vs/active-recall-vs-spaced-repetition/", "Active recall vs spaced repetition"], ["guides/blurting-method/", "The blurting method"], ["guides/study-myths/", "Study myths"]] },
  { slug: "blurting-method", group: "method", title: "The Blurting Method: How to Do It (with a Template) · Gradify", description: "The blurting revision method explained: write everything you remember on a blank page, check it in another colour, and target the gaps. With printable blurting sheets.",
    h1: "The blurting method: how to do it properly", answer: "Blurting is writing down everything you can remember about a topic on a blank page, without notes, then checking it against your notes in a different colour and filling the gaps. It's active recall for whole topics, and the gaps you fill in colour are exactly what to revise next.",
    sections: [
      T("How do I do the blurting method?", `<ol><li>Pick one topic and set a timer (10 to 15 minutes).</li><li>Write or draw everything you remember: definitions, processes, examples, diagrams.</li><li>Open your notes and check, adding what you missed in a different colour.</li><li>Make flashcards for the coloured parts.</li><li>Blurt the same topic again in two or three days: there should be less colour.</li></ol>`, "The coloured corrections are your revision list."),
      T("Where can I get blurting sheets?", `<p>Every <a href="/topics/">topic page</a> has a <b>Print blurting sheet</b> button: it prints the topic's headings and prompts with space to write, and the answers stay on the page to check against.</p>`),
      T("Blurting or flashcards?", `<p>Blurting tests whole topics and how ideas connect; flashcards test individual facts and definitions. Use blurting to find gaps and flashcards to fix them. More in <a href="/vs/blurting-vs-flashcards/">blurting vs flashcards</a>.</p>`, "", ["You blurted a topic and half the page is in correction colour. What next?", "Make flashcards for the corrections, review them over the next few days, and blurt the topic again in 2 or 3 days."]),
    ],
    faq: [["Does blurting work?", "Yes: it's a form of retrieval practice, which has strong research support. Checking and correcting afterwards is essential."]],
    links: [["topics/", "Topic pages with blurting sheets"], ["guides/active-recall/", "Active recall guide"], ["vs/blurting-vs-flashcards/", "Blurting vs flashcards"]] },
  { slug: "free-alternatives-to-paid-study-apps", group: "method", title: "Free Alternatives to Paid Study Apps (No Sign-Up Options) · Gradify", description: "Free ways to do what paid study subscriptions charge for: AI flashcards from notes, spaced repetition, mind maps, study planners and timers, some with no sign-up.",
    h1: "Free alternatives to paid study apps", answer: "Most of what study subscriptions charge for has a free option: Anki for spaced repetition, Gradify for flashcards and mind maps made from your notes (no account needed to try it), the free calculators and planners on this site, and your phone's built-in focus mode. Paid plans mostly buy convenience and limits removed.",
    sections: [
      T("Is there a free AI flashcard maker without sign-up?", `<p>Gradify's <a href="/pdf-to-flashcards/">PDF to flashcards</a> makes your first pack from a PDF or pasted notes with no account, and links each card to the line it came from. Anki is free (except on iPhone) but you type cards yourself or import them.</p>`, "Try before you pay: most paid features have a free version."),
      T("Free spaced repetition and planners", `<ul><li>Spaced repetition: Anki (free on desktop, web and Android), Gradify (free), or the <a href="/tools/spaced-repetition-schedule/">schedule generator</a> for paper cards.</li><li>Planners: the <a href="/tools/cram-planner/">cram</a>, <a href="/tools/deadline-planner/">deadline</a> and <a href="/tools/exam-timetable-planner/">exam timetable</a> planners.</li><li>Focus: the <a href="/tools/study-timer/">study timer</a> and your phone's focus mode.</li></ul>`),
      T("What do paid plans actually add?", `<p>Usually higher limits on AI features, ad removal, offline use and extra study modes. Check what the free tier of any tool limits before you subscribe, and see our <a href="/compare/">honest comparisons</a>.</p>`),
    ],
    faq: [["What's the best free alternative to Quizlet Plus?", "For shared sets, Anki's community decks; for making cards from your own notes, Gradify; for importing Quizlet sets, Knowt's free plan. See our Quizlet Plus alternatives page."]],
    links: [["compare/quizlet-plus-alternatives/", "Quizlet Plus alternatives"], ["tools/", "Free study tools"], ["compare/", "All comparisons"]] },
  // ---------- survival and migration ----------
  { slug: "medicinal-chemistry-labs-survival", group: "survival", title: "First-Year Medicinal Chemistry and Pharmacology Labs: Survival Guide · Gradify", description: "How to survive first-year medicinal chemistry and pharmacology labs: pre-lab prep, lab books, calculations, write-ups and revising mechanisms and drug classes.",
    h1: "Surviving first-year medicinal chemistry and pharmacology labs", answer: "Labs reward preparation: read the script and do the calculations before you arrive, keep a lab book anyone could follow, and write up within 48 hours while you remember. For the exams, learn drug classes and mechanisms with flashcards and practise the calculations until the units are automatic.",
    sections: [
      T("How do I prepare for a lab?", `<ul><li>Read the script the day before and write a one-line aim.</li><li>Do every calculation in advance (moles, dilutions, yields), with units.</li><li>Note the hazards and what you'd do if something spilled.</li></ul>`, "Do the calculations before the lab, not during it."),
      T("How do I keep a good lab book?", `<p>Date, aim, what you actually did (not what the script said), raw data with units in tables, observations, and anything that went wrong. Never write on scraps.</p>`),
      T("How do I revise pharmacology?", `<p>One card per drug class: mechanism, uses, key adverse effects, monitoring. Group by system. The free <a href="/topics/pharmacy/">pharmacy</a> and <a href="/topics/medicine/">medicine</a> topic pages have sample cards and quizzes.</p>`, "", ["What four things should a drug-class flashcard cover?", "Mechanism of action, main uses, key adverse effects or cautions, and monitoring or interactions."]),
    ],
    faq: [["How do I get good marks on lab reports?", "Answer the aim, explain how you controlled variables, present data with units and uncertainties, and discuss limitations with their effect on the result."]],
    links: [["checklists/lab-report/", "Lab report checklist"], ["tools/unit-converter/", "Unit converter"], ["guides/organic-mechanisms-revision/", "Revising organic mechanisms"]] },
  { slug: "organic-mechanisms-revision", group: "survival", title: "How to Revise Organic Chemistry Mechanisms Without Rote Learning · Gradify", description: "Revise organic mechanisms by understanding electron flow: nucleophiles, electrophiles, curly arrows and a handful of patterns, then drawing them from memory.",
    h1: "How to revise organic mechanisms without rote learning", answer: "Most organic mechanisms are combinations of a few patterns: a nucleophile attacks an electrophile, a leaving group leaves, a proton moves. Learn to spot the nucleophile and electrophile and draw curly arrows from electron-rich to electron-poor, then practise drawing each mechanism from memory on a blank page.",
    sections: [
      T("What's the key to organic mechanisms?", `<p>Curly arrows show electron pairs moving, always from a lone pair or bond (electron-rich) to an atom that can accept them (electron-poor). If you can say why each arrow goes where it goes, you don't need to memorise the mechanism.</p>`, "Arrows go from electron-rich to electron-poor, always."),
      T("Which patterns cover most mechanisms?", `<ul><li>Nucleophilic substitution (SN1, SN2)</li><li>Elimination (E1, E2)</li><li>Electrophilic addition to alkenes</li><li>Nucleophilic addition to carbonyls</li><li>Electrophilic substitution of arenes</li></ul><p>See <a href="/topics/chemistry/">chemistry topics</a> for sample cards and quizzes.</p>`),
      T("How do I practise mechanisms?", `<p>Blank page, name the reaction, draw the mechanism with every arrow and charge, then check. Do it again in two days. That's <a href="/guides/blurting-method/">blurting</a> for chemistry.</p>`, "", ["In SN2, why does the nucleophile attack from the side opposite the leaving group?", "The C–X σ* orbital is on the far side, and the leaving group blocks the front: backside attack gives inversion of configuration."]),
    ],
    faq: [["How do you remember organic chemistry reactions?", "Understand the electron flow rather than memorising: identify nucleophile and electrophile, draw arrows from electron-rich to electron-poor, and practise from a blank page with spaced reviews."]],
    links: [["topics/chemistry/", "Chemistry topics"], ["guides/active-recall-for-science/", "Active recall for science"], ["guides/medicinal-chemistry-labs-survival/", "Medicinal chemistry labs guide"]] },
  { slug: "history-source-essays", group: "survival", title: "How to Write a History Source Essay (Provenance, Content, Context) · Gradify", description: "Structure a history source or interpretation essay: provenance, content and context, judging value and reliability, and reaching a supported conclusion.",
    h1: "How to write a history source essay", answer: "Judge each source on three things: its provenance (who made it, when, why and for whom), its content (what it says and what it leaves out) and its context (what you know about the period). Then reach a judgement on how valuable it is for the specific question asked.",
    sections: [
      T("How do I analyse a historical source?", `<ul><li><b>Provenance</b>: author, date, type, audience, purpose. How does each affect what it says?</li><li><b>Content</b>: what it claims, its tone, its omissions.</li><li><b>Context</b>: your own knowledge that confirms or challenges it.</li></ul>`, "Every judgement about a source links provenance or context to the question."),
      T("Value or reliability?", `<p>A biased source can still be valuable: propaganda is excellent evidence of what a government wanted people to believe. Always judge value <i>for the question asked</i>.</p>`, "", ["Is a biased source useless?", "No: it can be very valuable evidence of attitudes, intentions or propaganda, depending on the question."]),
      T("How do I structure the essay?", `<p>One paragraph per source (or per theme across sources), each ending with a judgement, then a conclusion that compares them and answers the question. The <a href="/tools/essay-outline-helper/">essay outline helper</a> builds the plan.</p>`),
    ],
    faq: [["What is provenance in history?", "Where a source comes from: who made it, when, why, for whom and in what form. It shapes how far you can trust it for a particular question."]],
    links: [["topics/history/", "History topics"], ["checklists/critical-analysis/", "Critical analysis checklist"], ["tools/essay-outline-helper/", "Essay outline helper"]] },
  { slug: "export-quizlet-sets", group: "switch", title: "How to Export Quizlet Sets and Study Them Elsewhere · Gradify", description: "Export a Quizlet set you made, import it into Anki or Gradify, and check every card against your notes. Step by step, with what to watch for.",
    h1: "How to export your Quizlet sets", answer: "Quizlet lets you export sets you created as text: open the set, choose Export from the ⋯ menu, and copy the terms. Paste them into Anki (File → Import) or into Gradify's notes, and Gradify turns them into cards checked against your own notes.",
    sections: [
      T("How do I export a Quizlet set?", `<ol><li>Open a set you created on the Quizlet website.</li><li>Click the ⋯ (more) menu and choose <b>Export</b>.</li><li>Choose how terms and definitions are separated (a tab or comma is easiest).</li><li>Copy the text.</li></ol><p>Export is available for sets you made. Menus change, so if you can't see it, check Quizlet's help centre.</p>`, "Export works for your own sets: copy them as text."),
      T("How do I import into Anki or Gradify?", `<p><b>Anki:</b> save the text as a .txt file, then File → Import and match the separator. <b>Gradify:</b> paste the text into <a href="/app.html#/new">Notes Studio</a>, ideally alongside your lecture notes so each card can be checked against them.</p>`),
      T("What should I check after moving?", `<p>Formatting and images may not survive. Check cards with formulas, and delete duplicates.</p>`, "", ["Why paste your lecture notes alongside an exported set?", "So each card can be checked against your own course material, catching errors in old or shared sets."]),
    ],
    faq: [["Can I export someone else's Quizlet set?", "Export is designed for sets you created. For other people's sets, check the creator's permission and Quizlet's terms."]],
    links: [["compare/gradify-vs-quizlet/", "Gradify vs Quizlet"], ["compare/quizlet-plus-alternatives/", "Quizlet Plus alternatives"], ["pdf-to-flashcards/", "PDF to flashcards"]] },
  { slug: "goodnotes-notion-pdf-to-mind-map", group: "switch", title: "Turn GoodNotes or Notion Notes into Flashcards and Mind Maps · Gradify", description: "Export GoodNotes or Notion notes as PDF or Markdown and turn them into source-checked flashcards and a mind map, free. Step by step.",
    h1: "Turn GoodNotes or Notion notes into flashcards and mind maps", answer: "Export your notes (GoodNotes: Share → Export → PDF; Notion: ⋯ → Export → Markdown or PDF), then upload the file to Gradify's Notes Studio. You get flashcards linked to the lines they came from and an editable mind map, free.",
    sections: [
      T("How do I export from GoodNotes?", `<p>Open the notebook, tap Share (or Export) and choose PDF. Handwriting needs to be converted to text first: use Gradify's Handwriting to text tool in the app, or GoodNotes' own conversion.</p>`, "Typed or converted text works best: PDFs need selectable text."),
      T("How do I export from Notion?", `<p>Open the page, click ⋯ → Export, and choose Markdown & CSV or PDF. Markdown keeps headings, which helps the mind map.</p>`),
      T("Then what?", `<p>Upload to <a href="/app.html#/new">Notes Studio</a>, check the cards marked <i>to check</i>, and start reviewing. See <a href="/lecture-notes-to-mind-map/">lecture notes to mind map</a>.</p>`, "", ["Why do headings in your notes help?", "They become the branches of the mind map and help group cards by topic."]),
    ],
    faq: [["Can I make flashcards from handwritten notes?", "Yes, once the handwriting is converted to text. Gradify's Handwriting to text tool or your notes app's conversion can do it."]],
    links: [["lecture-notes-to-mind-map/", "Lecture notes to mind map"], ["pdf-to-flashcards/", "PDF to flashcards"], ["guides/notion-study-template/", "Notion study template"]] },
  { slug: "notion-study-template", group: "switch", title: "Free Notion Study Template (Revision Dashboard) · Gradify", description: "A free Notion revision dashboard: modules, a study schedule, an active-recall tracker and links to free planners and timers. Download it as Markdown and import.",
    h1: "Free Notion study template", answer: "Download the template below as a Markdown file and import it into Notion (Settings → Import → Text & Markdown). You get a revision dashboard with a module list, a weekly schedule, an active-recall tracker and embeds for a live exam countdown and study timer.",
    sections: [
      T("What's in the template?", `<ul><li>Modules table: credits, assessments, exam dates, confidence.</li><li>Weekly schedule with review slots.</li><li>Active-recall tracker: topic, last tested, score, next review.</li><li>Embeds: the <a href="/tools/exam-countdown/">exam countdown</a> and <a href="/tools/study-timer/">study timer</a> (Notion's /embed block).</li></ul><p><a class="btn btn-primary" href="/templates/notion-study-dashboard.md" download><span>Download the Notion template (.md)</span></a></p>`, "Import it, then embed a live countdown with /embed."),
      T("How do I embed a Gradify tool in Notion?", `<p>On any tool page, press <b>Embed</b> under the tool to copy its code, or copy the page link. In Notion, type <code>/embed</code>, paste the link, and resize. Topic pages can be embedded the same way (<b>Embed this deck</b>).</p>`, "", ["Which Notion command embeds a web tool?", "/embed, then paste the link."]),
    ],
    faq: [["Is the Notion template free?", "Yes. Download it as Markdown and import it into any Notion workspace."]],
    links: [["tools/", "Free study tools"], ["templates/", "Printable templates"], ["guides/goodnotes-notion-pdf-to-mind-map/", "Notion notes to flashcards"]] },
];

